package models

import "time"

// Notification represents one notification delivered to a user.
//
// Notifications are an information layer. They point users toward
// events or records generated by other Agro-Shield modules such as
// orders, marketplace activity, messages, learning, events,
// announcements, and system events.
type Notification struct {
	ID     int `json:"id"`
	UserID int `json:"user_id"`

	// Notification classification.
	Type string `json:"type"`

	// Notification content.
	Title   string `json:"title"`
	Message string `json:"message"`

	// Optional reference to the record that generated the notification.
	//
	// Both fields are nullable in PostgreSQL because a notification
	// does not always need to point to another record.
	ReferenceType *string `json:"reference_type,omitempty"`
	ReferenceID   *int    `json:"reference_id,omitempty"`

	// Read state.
	IsRead bool `json:"is_read"`

	// Timestamp.
	CreatedAt time.Time `json:"created_at"`
}
